package com.example.panels.servers

import android.content.Context
import com.example.data.security.SecureStorage
import org.json.JSONArray
import org.json.JSONObject

/**
 * Encrypted provenance + client-verification ledger for profiles generated by managed VPS tools.
 * This does not change manually imported nodes or replace Room's actual profile repository.
 */
data class ManagedNodeRecord(
    val serverId: String,
    val serviceId: String,
    val profileId: String,
    val state: State,
    val updatedAt: Long,
    /** Coarse network category (wifi / ethernet / cell:MCCMNC), never SSID, BSSID or SIM identifier. */
    val networkKey: String = ""
) {
    enum class State { CONFIGURED, TESTING, AVAILABLE, STALE, INVALID }
}

class SmartNodeStore(context: Context) {
    private val secure = SecureStorage(context.applicationContext)

    @Synchronized
    fun all(): List<ManagedNodeRecord> = decode(secure.getAndDecrypt(KEY, "[]"))

    @Synchronized
    fun configured(serverId: String, serviceId: String, profileId: String, now: Long = System.currentTimeMillis()) {
        require(serverId.isNotBlank() && serviceId.isNotBlank() && profileId.isNotBlank())
        val records = all()
        // Even when a generated profile ID did not change, reinstall/key rotation invalidates
        // the old test. Never retain AVAILABLE across a server mutation without a new phone probe.
        persist(records.filterNot { it.serverId == serverId && it.serviceId == serviceId } +
            ManagedNodeRecord(serverId, serviceId, profileId, ManagedNodeRecord.State.CONFIGURED, now))
    }

    @Synchronized
    fun testing(serverId: String, serviceId: String, profileId: String, now: Long = System.currentTimeMillis()) {
        change(serverId, serviceId, profileId, ManagedNodeRecord.State.TESTING, now)
    }

    /**
     * [trafficVerified] MUST come from EngineProbe/ServerTester using a real request through
     * the tunnel. A successful SSH check, systemd active state or synthetic ping is insufficient.
     */
    @Synchronized
    fun result(serverId: String, serviceId: String, profileId: String, trafficVerified: Boolean,
               now: Long = System.currentTimeMillis(), networkKey: String = "") {
        change(serverId, serviceId, profileId,
            if (trafficVerified && networkKey.isNotBlank()) ManagedNodeRecord.State.AVAILABLE
            else ManagedNodeRecord.State.STALE, now, networkKey)
    }

    private fun change(serverId: String, serviceId: String, profileId: String,
                       status: ManagedNodeRecord.State, now: Long, networkKey: String = "") {
        val list = all()
        val entry = list.firstOrNull { it.serverId == serverId && it.serviceId == serviceId }
        require(entry != null && entry.profileId == profileId) { "Managed node identity mismatch; reimport and retest." }
        persist(list.map {
            if (it == entry) it.copy(state = status, updatedAt = now, networkKey = networkKey.take(48)) else it
        })
    }

    private fun persist(records: List<ManagedNodeRecord>) =
        secure.encryptAndSave(KEY, JSONArray().apply {
            records.takeLast(MAX).forEach { entry ->
                put(JSONObject().put("serverId", entry.serverId).put("serviceId", entry.serviceId)
                    .put("profileId", entry.profileId).put("state", entry.state.name)
                    .put("updatedAt", entry.updatedAt).put("networkKey", entry.networkKey))
            }
        }.toString())

    companion object {
        private const val KEY = "managed_nodes_provenance_v1"
        private const val MAX = 500
        fun decode(raw: String): List<ManagedNodeRecord> {
            val array = JSONArray(raw) // corrupted record cannot promote a node to AVAILABLE
            return (0 until array.length()).map { index ->
                array.getJSONObject(index).let {
                    ManagedNodeRecord(it.getString("serverId"), it.getString("serviceId"),
                        it.getString("profileId"), ManagedNodeRecord.State.valueOf(it.getString("state")),
                        it.getLong("updatedAt"), it.optString("networkKey"))
                }
            }
        }
    }
}
